"""Compressed byte-sequence algebra, byte expressions and templates.

Byte sequences are immutable ropes (leaf / concatenation / repetition) that
cache their exact length and the protocol fingerprint
``sum((b[i]+1)*257**(N-1-i)) mod 2**64``.  Very large objects and repeated
boundary probes are therefore represented without storing their expanded
contents; only bounded windows are ever materialized.
"""
import ast
import hashlib
import keyword
import re

MAX = (1 << 63) - 1
MOD = 1 << 64
BASE = 257
EXPR_LIMIT = 8192
TEMPLATE_LIMIT = 65536
DEPTH_LIMIT = 128
IDENTIFIER = re.compile(r'[A-Za-z][A-Za-z0-9_]{0,31}\Z', re.ASCII)
RANDOM_TOKEN = '<<random_string>>'
FETCH = 8192
TRIM = 1 << 16
MATERIALIZE_LIMIT = 1 << 22


class ByteSequence:
    """Immutable compressed byte sequence.

    ``tag`` is ``'L'`` (``a`` holds the bytes), ``'C'`` (``a``/``b`` are the
    concatenated parts) or ``'R'`` (``a`` is repeated ``b`` times).
    """
    __slots__ = ('tag', 'a', 'b', 'n', 'h')

    def __init__(self, tag, a, b, n, h):
        self.tag = tag
        self.a = a
        self.b = b
        self.n = n
        self.h = h


EMPTY = ByteSequence('L', b'', 0, 0, 0)


def hash_bytes(data):
    """Exact protocol fingerprint value of a literal byte string."""
    h = 0
    for c in data:
        h = (h * BASE + c + 1) % MOD
    return h


def leaf(data):
    if not data:
        return EMPTY
    if type(data) is not bytes:
        data = bytes(data)
    return ByteSequence('L', data, 0, len(data), hash_bytes(data))


def _repeat_value(h, length, count):
    """Fingerprint value of ``count`` repetitions of a block."""
    if count <= 0:
        return 0
    if count == 1:
        return h
    half = count >> 1
    value = _repeat_value(h, length, half)
    value = (value * pow(BASE, length * half, MOD) + value) % MOD
    if count & 1:
        value = (value * pow(BASE, length, MOD) + h) % MOD
    return value


def concat(left, right):
    """Concatenation of two byte sequences."""
    if left.n == 0:
        return right
    if right.n == 0:
        return left
    n = left.n + right.n
    if n > MAX:
        raise ValueError('byte sequence length')
    h = (left.h * pow(BASE, right.n, MOD) + right.h) % MOD
    return ByteSequence('C', left, right, n, h)


def repeat(base, count):
    """``count`` repetitions of a byte sequence."""
    if count <= 0 or base.n == 0:
        return EMPTY
    if count == 1:
        return base
    n = base.n * count
    if n > MAX:
        raise ValueError('byte sequence length')
    return ByteSequence('R', base, count, n, _repeat_value(base.h, base.n, count))


def concat_all(items):
    """Order preserving concatenation of many sequences, kept balanced."""
    items = [item for item in items if item.n]
    if not items:
        return EMPTY
    if len(items) == 1:
        return items[0]
    total = 0
    for item in items:
        total += item.n
        if total > MAX:
            raise ValueError('byte sequence length')
    while len(items) > 1:
        merged = []
        last = len(items) - 1
        for index in range(0, last, 2):
            merged.append(concat(items[index], items[index + 1]))
        if len(items) & 1:
            merged.append(items[last])
        items = merged
    return items[0]


def size(node):
    """Logical byte length of a sequence."""
    return 0 if node is None else node.n


def fingerprint(node):
    """Protocol fingerprint object of a sequence."""
    if node is None:
        node = EMPTY
    return {'n': node.n, 'h': '%016x' % node.h}


def empty_fingerprint():
    return {'n': 0, 'h': '0000000000000000'}


def _split(node, lo, hi):
    """Yield (sub-node, low, high) pieces covering node[lo:hi] in order."""
    tag = node.tag
    if tag == 'L':
        yield ('r', node, lo, hi)
    elif tag == 'C':
        left = node.a
        ln = left.n
        if hi <= ln:
            yield ('r', left, lo, hi)
        elif lo >= ln:
            yield ('r', node.b, lo - ln, hi - ln)
        else:
            yield ('r', node.b, 0, hi - ln)
            yield ('s', left)
    else:
        base = node.a
        bl = base.n
        first = lo // bl
        offset = lo % bl
        last = (hi - 1) // bl
        lastoff = (hi - 1) % bl
        if first == last:
            yield ('r', base, offset, lastoff + 1)
        else:
            yield ('r', base, 0, lastoff + 1)
            middle = last - first - 1
            if middle > 0:
                yield ('s', repeat(base, middle))
            if offset:
                yield ('r', base, offset, bl)


def slice_seq(seq, lo, hi):
    """Byte slice ``seq[lo:hi]`` as a compressed sequence."""
    if lo >= hi:
        return EMPTY
    if lo == 0 and hi == seq.n:
        return seq
    parts = []
    stack = [('r', seq, lo, hi)]
    while stack:
        item = stack.pop()
        if item[0] == 's':
            parts.append(item[1])
            continue
        node, low, high = item[1], item[2], item[3]
        if low >= high:
            continue
        if low == 0 and high == node.n:
            parts.append(node)
            continue
        stack.extend(reversed(list(_split(node, low, high))))
    return concat_all(parts)


def range_hash(seq, lo, hi):
    """Fingerprint (length, value) of ``seq[lo:hi]`` without materializing."""
    if lo >= hi:
        return 0, 0
    if lo == 0 and hi == seq.n:
        return seq.n, seq.h
    total_n = 0
    total_h = 0
    stack = [('r', seq, lo, hi)]
    while stack:
        item = stack.pop()
        if item[0] == 's':
            node = item[1]
            total_h = (total_h * pow(BASE, node.n, MOD) + node.h) % MOD
            total_n += node.n
            continue
        node, low, high = item[1], item[2], item[3]
        if low >= high:
            continue
        if low == 0 and high == node.n:
            total_h = (total_h * pow(BASE, node.n, MOD) + node.h) % MOD
            total_n += node.n
            continue
        if node.tag == 'L':
            data = node.a[low:high]
            total_h = (total_h * pow(BASE, len(data), MOD) + hash_bytes(data)) % MOD
            total_n += len(data)
            continue
        stack.extend(reversed(list(_split(node, low, high))))
    return total_n, total_h


def materialize(seq, lo, hi):
    """Return the literal bytes of ``seq[lo:hi]`` (bounded windows only)."""
    if lo >= hi:
        return b''
    if hi - lo > MATERIALIZE_LIMIT:
        raise ValueError('bounded materialization')
    parts = []
    stack = [('r', seq, lo, hi)]
    while stack:
        item = stack.pop()
        if item[0] == 's':
            node = item[1]
            if node.tag == 'L':
                parts.append(node.a)
            elif node.tag == 'R':
                parts.append(node.a * node.b)
            else:
                stack.append(('s', node.b))
                stack.append(('s', node.a))
            continue
        node, low, high = item[1], item[2], item[3]
        if low >= high:
            continue
        if low == 0 and high == node.n:
            stack.append(('s', node))
            continue
        if node.tag == 'L':
            parts.append(node.a[low:high])
            continue
        stack.extend(reversed(list(_split(node, low, high))))
    return b''.join(parts)


class ByteWindow:
    """Sequential bounded reader over a compressed sequence."""
    __slots__ = ('seq', 'total', 'pos', 'buf', 'start')

    def __init__(self, seq):
        self.seq = seq
        self.total = seq.n
        self.pos = 0
        self.buf = bytearray()
        self.start = 0

    def view(self, count):
        """Return (buffer, offset, available) covering the next bytes."""
        pos = self.pos
        if pos < self.start or pos > self.start + len(self.buf):
            self.start = pos
            self.buf = bytearray()
        elif pos - self.start > TRIM and self.buf:
            drop = pos - self.start
            del self.buf[:drop]
            self.start = pos
        end = pos + count
        if end > self.total:
            end = self.total
        bufend = self.start + len(self.buf)
        if end > bufend:
            fetch = pos + (count if count > FETCH else FETCH)
            if fetch < end:
                fetch = end
            if fetch > self.total:
                fetch = self.total
            if fetch > bufend:
                self.buf += materialize(self.seq, bufend, fetch)
        offset = pos - self.start
        return self.buf, offset, end - pos

    def advance(self, count):
        self.pos += count


def _endpoint(node):
    if node is None:
        return None
    if isinstance(node, ast.Constant) and type(node.value) is int:
        value = node.value
        if 0 <= value <= MAX:
            return value
    raise ValueError('slice endpoint')


class Context:
    """Definition table, byte-expression evaluator and template compiler."""

    def __init__(self, definitions, seed):
        self.seed = seed
        self.env = {}
        for row in definitions:
            if type(row) is not list or len(row) != 2:
                raise ValueError('definition pair')
            name, source = row
            if type(name) is not str or type(source) is not str:
                raise ValueError('definition types')
            try:
                name.encode('utf8')
                source.encode('utf8')
            except UnicodeEncodeError:
                raise ValueError('definition encoding') from None
            if IDENTIFIER.fullmatch(name) is None or keyword.iskeyword(name):
                raise ValueError('definition name')
            if name in self.env:
                raise ValueError('duplicate definition')
            if len(source) > EXPR_LIMIT:
                raise ValueError('expression source')
            self.env[name] = self.expression(source)

    def expression(self, source):
        """Evaluate a byte expression source into a byte sequence."""
        if type(source) is not str:
            raise ValueError('expression type')
        if len(source) > EXPR_LIMIT:
            raise ValueError('expression source')
        try:
            source.encode('utf8')
        except UnicodeEncodeError:
            raise ValueError('expression encoding') from None
        try:
            tree = ast.parse(source, mode='eval')
        except (SyntaxError, ValueError, MemoryError, RecursionError):
            raise ValueError('expression syntax') from None
        body = tree.body
        if _ast_depth(body) > DEPTH_LIMIT:
            raise ValueError('expression depth')
        kind, value = self._eval(body)
        if kind != 'seq':
            raise ValueError('expression must be bytes')
        return value

    def _eval(self, node):
        if isinstance(node, ast.Constant):
            value = node.value
            if type(value) is int:
                if 0 <= value <= MAX:
                    return 'int', value
                raise ValueError('integer literal')
            if type(value) is str:
                try:
                    data = value.encode('utf8')
                except UnicodeEncodeError:
                    raise ValueError('string literal') from None
                return 'seq', leaf(data)
            if type(value) is bytes:
                return 'seq', leaf(value)
            raise ValueError('literal')
        if isinstance(node, ast.Name):
            if node.id not in self.env:
                raise ValueError('undefined name')
            return 'seq', self.env[node.id]
        if isinstance(node, ast.BinOp):
            if isinstance(node.op, ast.Add):
                left = self._eval(node.left)
                right = self._eval(node.right)
                if left[0] != 'seq' or right[0] != 'seq':
                    raise ValueError('concatenation operands')
                return 'seq', concat(left[1], right[1])
            if isinstance(node.op, ast.Mult):
                left = self._eval(node.left)
                right = self._eval(node.right)
                if left[0] == 'seq' and right[0] == 'int':
                    return 'seq', repeat(left[1], right[1])
                if left[0] == 'int' and right[0] == 'seq':
                    return 'seq', repeat(right[1], left[1])
                raise ValueError('repetition operands')
            raise ValueError('operator')
        if isinstance(node, ast.Subscript):
            if not isinstance(node.slice, ast.Slice):
                raise ValueError('slice')
            if node.slice.step is not None:
                raise ValueError('slice step')
            base = self._eval(node.value)
            if base[0] != 'seq':
                raise ValueError('slice base')
            low = _endpoint(node.slice.lower)
            high = _endpoint(node.slice.upper)
            length = base[1].n
            if low is None:
                low = 0
            if high is None:
                high = length
            if not 0 <= low <= high <= length:
                raise ValueError('slice bounds')
            return 'seq', slice_seq(base[1], low, high)
        raise ValueError('unsupported syntax')

    def template(self, value, coordinate):
        """Compile a JSON string template into a byte sequence."""
        if type(value) is not str:
            raise ValueError('template type')
        try:
            value.encode('utf8')
        except UnicodeEncodeError:
            raise ValueError('template encoding') from None
        if len(value) >= 4 and value[:2] == '{{' and value[-2:] == '}}':
            return self.expression(value[2:-2].strip())
        if len(value) > TEMPLATE_LIMIT:
            raise ValueError('template source')
        if RANDOM_TOKEN in value:
            pieces = value.split(RANDOM_TOKEN)
            out = bytearray()
            last = len(pieces) - 1
            for index, piece in enumerate(pieces):
                out += piece.encode('utf8')
                if index < last:
                    out += _random_hex(self.seed, coordinate, index)
            return leaf(bytes(out))
        return leaf(value.encode('utf8'))


def _random_hex(seed, coordinate, occurrence):
    payload = '%s/%s/%d' % (seed, coordinate, occurrence)
    digest = hashlib.sha256(payload.encode('utf8')).hexdigest()[:20]
    return digest.encode('ascii')


def _ast_depth(node):
    """Maximum number of AST child edges below (and including) ``node``."""
    best = 0
    stack = [(node, 0)]
    while stack:
        current, depth = stack.pop()
        if depth > best:
            best = depth
        for child in ast.iter_child_nodes(current):
            stack.append((child, depth + 1))
    return best
